#!/usr/bin/env python3
"""Cold-chain disposition register (CCDR).

A small, self-contained HTTP service that holds the temperature-logger records
for inbound pharmaceutical consignments and the disposition decisions made
against them.  It is started by the trusted launcher as the `appsvc` account so
its state directory is not writable by the solver; every change therefore has to
arrive through a declared tool call.

State lives under /var/lib/harbor-service so a fresh instance really starts
fresh.  The seed corpus is read once, from the read-only public tree, and is
never written back.
"""

import http.server
import json
import os
import socketserver
import sys
import threading
import urllib.parse

STATE_DIR = "/var/lib/harbor-service"
STATE_PATH = os.path.join(STATE_DIR, "state.json")
SEED_PATH = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "seed.json"
)
PORT = 8421

DECISIONS = ("release", "quarantine", "destroy")
REASON_CODES = (
    "NO_EXCURSION",
    "WITHIN_ALLOWANCE",
    "ALLOWANCE_EXCEEDED",
    "CRIT_EXCEEDED",
    "DATA_INSUFFICIENT",
)

_LOCK = threading.Lock()
_STATE = None


# --------------------------------------------------------------------------
# state


def _load_seed():
    with open(SEED_PATH, "r", encoding="utf-8") as fh:
        return json.load(fh)


def _init_state():
    seed = _load_seed()
    shipments = {}
    for sh in seed["shipments"]:
        shipments[sh["shipment"]] = {
            "shipment": sh["shipment"],
            "consignment": sh["consignment"],
            "product_class": sh["product_class"],
            "description": sh["description"],
            "status": sh["status"],
            "decision": sh["decision"],
            "reason_code": sh["reason_code"],
            "readings": sh["readings"],
        }
    consignments = {c["consignment"]: dict(c) for c in seed["consignments"]}
    return {
        "policy": seed["policy"],
        "consignments": consignments,
        "shipments": shipments,
        "ledger": [],
        "seq": 0,
    }


def _persist():
    tmp = STATE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(_STATE, fh, indent=1, sort_keys=True)
        fh.write("\n")
    os.replace(tmp, STATE_PATH)


def _boot():
    global _STATE
    try:
        os.makedirs(STATE_DIR, mode=0o750, exist_ok=True)
    except OSError as exc:
        sys.stderr.write("ccdr: cannot create %s: %s\n" % (STATE_DIR, exc))
        raise
    _STATE = _init_state()
    _persist()


def _record(action, detail, accepted, message):
    _STATE["seq"] += 1
    entry = {
        "seq": _STATE["seq"],
        "action": action,
        "accepted": bool(accepted),
        "message": message,
    }
    entry.update(detail)
    _STATE["ledger"].append(entry)
    return entry


# --------------------------------------------------------------------------
# handlers


def h_policy(_params):
    pol = json.loads(json.dumps(_STATE["policy"]))
    pol["decisions"] = list(DECISIONS)
    pol["reason_codes"] = list(REASON_CODES)
    return 200, pol


def h_consignments(_params):
    rows = []
    for name in sorted(_STATE["consignments"]):
        c = _STATE["consignments"][name]
        total = sum(
            1 for s in _STATE["shipments"].values() if s["consignment"] == name
        )
        decided = sum(
            1
            for s in _STATE["shipments"].values()
            if s["consignment"] == name and s["decision"] is not None
        )
        rows.append(
            {
                "consignment": name,
                "status": c["status"],
                "note": c["note"],
                "shipments": total,
                "dispositioned": decided,
            }
        )
    return 200, {"consignments": rows}


def h_shipments(params):
    want = params.get("consignment")
    rows = []
    for name in sorted(_STATE["shipments"]):
        s = _STATE["shipments"][name]
        if want and s["consignment"] != want:
            continue
        rows.append(
            {
                "shipment": s["shipment"],
                "consignment": s["consignment"],
                "product_class": s["product_class"],
                "description": s["description"],
                "status": s["status"],
                "decision": s["decision"],
                "reason_code": s["reason_code"],
                "reading_count": len(s["readings"]),
            }
        )
    if want and not rows and want not in _STATE["consignments"]:
        return 404, {"error": "unknown consignment %r" % want}
    return 200, {"shipments": rows}


def h_readings(params):
    sid = params.get("shipment")
    s = _STATE["shipments"].get(sid)
    if s is None:
        return 404, {"error": "unknown shipment %r" % sid}
    return 200, {
        "shipment": s["shipment"],
        "product_class": s["product_class"],
        "sample_interval_min": _STATE["policy"]["sample_interval_min"],
        "readings": s["readings"],
    }


def h_ledger(_params):
    return 200, {"ledger": _STATE["ledger"]}


def h_disposition(params):
    sid = params.get("shipment")
    decision = params.get("decision")
    reason = params.get("reason_code")
    detail = {"shipment": sid, "decision": decision, "reason_code": reason}

    s = _STATE["shipments"].get(sid)
    if s is None:
        _record("disposition", detail, False, "unknown shipment")
        _persist()
        return 404, {"error": "unknown shipment %r" % sid}
    if decision not in DECISIONS:
        _record("disposition", detail, False, "bad decision")
        _persist()
        return 400, {
            "error": "decision must be one of %s" % (list(DECISIONS),)
        }
    if reason not in REASON_CODES:
        _record("disposition", detail, False, "bad reason_code")
        _persist()
        return 400, {
            "error": "reason_code must be one of %s" % (list(REASON_CODES),)
        }

    detail["consignment"] = s["consignment"]
    s["decision"] = decision
    s["reason_code"] = reason
    s["status"] = {
        "release": "released",
        "quarantine": "quarantined",
        "destroy": "destroyed",
    }[decision]
    _record("disposition", detail, True, "recorded")
    _persist()
    return 200, {
        "shipment": sid,
        "consignment": s["consignment"],
        "status": s["status"],
        "decision": decision,
        "reason_code": reason,
        "recorded": True,
    }


def h_close(params):
    name = params.get("consignment")
    detail = {"consignment": name}
    c = _STATE["consignments"].get(name)
    if c is None:
        _record("close", detail, False, "unknown consignment")
        _persist()
        return 404, {"error": "unknown consignment %r" % name}
    pending = sorted(
        s["shipment"]
        for s in _STATE["shipments"].values()
        if s["consignment"] == name and s["decision"] is None
    )
    if pending:
        _record("close", detail, False, "pending shipments")
        _persist()
        return 409, {
            "error": "consignment has undispositioned shipments",
            "pending": pending,
        }
    c["status"] = "sealed"
    _record("close", detail, True, "sealed")
    _persist()
    return 200, {"consignment": name, "status": "sealed", "sealed": True}


ROUTES = {
    ("GET", "/policy"): h_policy,
    ("GET", "/consignments"): h_consignments,
    ("GET", "/shipments"): h_shipments,
    ("GET", "/ledger"): h_ledger,
    ("POST", "/shipments/disposition"): h_disposition,
    ("POST", "/consignments/close"): h_close,
}


def dispatch(method, path, params):
    fn = ROUTES.get((method, path))
    if fn is not None:
        return fn(params)
    parts = [p for p in path.split("/") if p]
    if method == "GET" and len(parts) == 3 and parts[0] == "shipments" \
            and parts[2] == "readings":
        merged = dict(params)
        merged["shipment"] = urllib.parse.unquote(parts[1])
        return h_readings(merged)
    return 404, {"error": "no such endpoint: %s %s" % (method, path)}


class Handler(http.server.BaseHTTPRequestHandler):
    server_version = "ccdr/1.0"

    def log_message(self, fmt, *args):  # keep stderr quiet
        pass

    def _reply(self, code, payload):
        body = json.dumps(payload, indent=1, sort_keys=True).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        params = {
            k: v[0]
            for k, v in urllib.parse.parse_qs(parsed.query).items()
        }
        with _LOCK:
            code, payload = dispatch("GET", parsed.path, params)
        self._reply(code, payload)

    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length else b""
        params = {}
        if raw:
            try:
                loaded = json.loads(raw.decode("utf-8"))
                if isinstance(loaded, dict):
                    params = loaded
            except (ValueError, UnicodeDecodeError):
                self._reply(400, {"error": "body must be a JSON object"})
                return
        for k, v in urllib.parse.parse_qs(parsed.query).items():
            params.setdefault(k, v[0])
        with _LOCK:
            code, payload = dispatch("POST", parsed.path, params)
        self._reply(code, payload)


class Server(socketserver.ThreadingTCPServer):
    allow_reuse_address = True
    daemon_threads = True


def main():
    _boot()
    srv = Server(("127.0.0.1", PORT), Handler)
    sys.stderr.write("ccdr: listening on 127.0.0.1:%d\n" % PORT)
    sys.stderr.flush()
    srv.serve_forever()


if __name__ == "__main__":
    main()

